The violated invariant is that every thread in a block must participate in the same block-wide barrier, unless the barrier’s enclosing condition is uniform across the block. Here, threads 0–69 reach `__syncthreads()` while threads 70–95 skip it, which is invalid synchronization—not a guarantee that every device will hang. A responsive host control endpoint does not establish GPU progress, and the not-ready completion event alone does not prove the cause; the sanitizer identifies the barrier violation.

This complete example moves the barrier outside the conditional and supports every `valid` value from 0 through 96:

```cuda
// sum.cu
#include <cuda_runtime.h>
#include <cerrno>
#include <cstdio>
#include <cstdlib>

#define CUDA_CHECK(expr) do {                                  \
    cudaError_t err = (expr);                                  \
    if (err != cudaSuccess) {                                  \
        std::fprintf(stderr, "%s: %s\n", #expr,                \
                     cudaGetErrorString(err));                \
        std::exit(EXIT_FAILURE);                              \
    }                                                         \
} while (0)

__global__ void sum_valid(const float* input, float* output,
                          int valid) {
    __shared__ float values[96];
    const unsigned int t = threadIdx.x;

    // Launch contract: exactly one block of 96 threads;
    // valid is in [0, 96], and input has at least valid elements.
    if (t < static_cast<unsigned int>(valid)) {
        values[t] = input[t];
    } else {
        values[t] = 0.0f;
    }

    __syncthreads();

    if (t == 0) {
        float sum = 0.0f;
        for (int i = 0; i < valid; ++i) {
            sum += values[i];
        }
        output[0] = sum;
    }
}

int main(int argc, char** argv) {
    if (argc > 2) {
        std::fprintf(stderr, "Usage: %s [valid: 0..96]\n", argv[0]);
        return EXIT_FAILURE;
    }

    int valid = 70;
    if (argc == 2) {
        char* end = nullptr;
        errno = 0;
        const long n = std::strtol(argv[1], &end, 10);
        if (errno != 0 || end == argv[1] || *end != '\0' ||
            n < 0 || n > 96) {
            std::fprintf(stderr, "valid must be an integer in [0, 96]\n");
            return EXIT_FAILURE;
        }
        valid = static_cast<int>(n);
    }

    float input[96];
    for (int i = 0; i < 96; ++i) input[i] = 1.0f;

    float* device_input = nullptr;
    float* device_output = nullptr;
    cudaStream_t stream;
    cudaEvent_t done;

    CUDA_CHECK(cudaStreamCreateWithFlags(&stream, cudaStreamNonBlocking));
    CUDA_CHECK(cudaEventCreateWithFlags(&done, cudaEventDisableTiming));
    CUDA_CHECK(cudaMalloc(reinterpret_cast<void**>(&device_input),
                          sizeof(input)));
    CUDA_CHECK(cudaMalloc(reinterpret_cast<void**>(&device_output),
                          sizeof(float)));
    CUDA_CHECK(cudaMemcpy(device_input, input, sizeof(input),
                          cudaMemcpyHostToDevice));

    sum_valid<<<1, 96, 0, stream>>>(device_input, device_output, valid);
    CUDA_CHECK(cudaGetLastError()); // Immediate launch errors only.
    CUDA_CHECK(cudaEventRecord(done, stream));
    CUDA_CHECK(cudaEventSynchronize(done)); // Wait/check execution.

    float result = 0.0f;
    CUDA_CHECK(cudaMemcpy(&result, device_output, sizeof(result),
                          cudaMemcpyDeviceToHost));
    std::printf("valid=%d, sum=%.1f\n", valid, result);

    CUDA_CHECK(cudaFree(device_input));
    CUDA_CHECK(cudaFree(device_output));
    CUDA_CHECK(cudaEventDestroy(done));
    CUDA_CHECK(cudaStreamDestroy(stream));
    return EXIT_SUCCESS;
}
```

Compile with `nvcc sum.cu -o sum` and run `./sum 70` on a CUDA-capable system.

Synchronization proof: all 96 threads write distinct shared-memory slots and then unconditionally reach the same barrier, which makes those writes visible before thread zero reads them. Input is read only when `t < valid`, so every input access is within the valid prefix; every shared-memory index is within 0–95. Thread zero always writes the output: for `valid=0` it writes zero without reading input, and for `valid=96` it sums all 96 initialized entries.
